// Registers the Workbox service worker generated by scripts/generate-sw.mjs.
//
// Behaviour mirrors the old vite-plugin-pwa `registerType: 'autoUpdate'`: a new
// SW installs and activates silently (skipWaiting + clientsClaim in the SW),
// then the page reloads once onto the fresh assets.
//
// The reliable "a new version took over" signal is `controllerchange`, not the
// narrower `updatefound -> statechange` path: with clientsClaim the new SW can
// take control via routes that never emit updatefound on the current page (e.g.
// it finished installing on a previous load). We listen for controllerchange
// and reload exactly once. The listener is only armed when the page is ALREADY
// controlled at load time, so a first-ever install (no prior controller) claims
// the page silently without a spurious reload.
import { IS_NATIVE_BUILD } from '../native/platform';

export function registerSW(): void {
  // The native App is offline via its on-device bundle; a service worker inside
  // the WebView would fight Capacitor's asset cache and cause stale-version bugs
  // (docs/adr/0002). Never register it there.
  if (IS_NATIVE_BUILD) return;
  if (typeof window === 'undefined') return;
  if (!('serviceWorker' in navigator)) return;
  // /sw.js only exists in production builds (emitted post-build, not in dev).
  if (!import.meta.env.PROD) return;

  if (navigator.serviceWorker.controller) {
    let reloaded = false;
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (reloaded) return;
      reloaded = true;
      window.location.reload();
    });
  }

  navigator.serviceWorker
    .register('/sw.js')
    .then((registration) => {
      const check = () => {
        registration.update().catch(() => {});
        void checkForUpdate();
      };
      check();
      // Installed PWAs (esp. iOS standalone) are resumed, not reloaded, so a
      // load-time check alone never fires again. Re-check on every resume and
      // hourly for long-lived tabs.
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') check();
      });
      setInterval(check, 60 * 60 * 1000);
    })
    .catch(() => {
      /* registration failures are non-fatal; the app still works online */
    });
}

export type UpdateCheck = 'current' | 'updating' | 'failed';

// Belt-and-braces over the SW update path: if the live deploy's build id
// differs from the one baked into this bundle, switch to the live build.
// Guarded once per target build so a CDN lag can't cause a reload loop. Also
// backs the "Check for updates" button.
export async function checkForUpdate(): Promise<UpdateCheck> {
  if (!navigator.onLine) return 'failed';
  try {
    const res = await fetch('/version.json', { cache: 'no-store' });
    if (!res.ok) return 'failed';
    const { build } = (await res.json()) as { build?: string };
    if (!build || build === __BUILD_ID__) return 'current';
    const key = 'pwa-forced-build';
    if (sessionStorage.getItem(key) === build) return 'current';
    sessionStorage.setItem(key, build);
    showUpdatingOverlay();
    // Purging only when no new SW is coming matters: SW jobs run one at a time
    // per scope, so an unregister() issued mid-install waits out the whole
    // precache download, and then the reload throws that download away.
    if (!(await newWorkerTakesOver())) {
      const regs = (await navigator.serviceWorker?.getRegistrations()) ?? [];
      await Promise.all(regs.map((r) => r.unregister()));
      const keys = await caches.keys();
      await Promise.all(keys.map((k) => caches.delete(k)));
    }
    window.location.reload();
    return 'updating';
  } catch {
    /* offline or malformed: keep running the cached version */
    return 'failed';
  }
}

// Waits for a new SW (skipWaiting + clientsClaim) to finish precaching the
// live build and take control. False when none is on the way: no SW, sw.js
// unchanged, or the install failed. A slow install counts as on the way: it
// keeps going after the reload and controllerchange reloads again when done.
async function newWorkerTakesOver(): Promise<boolean> {
  const sw = navigator.serviceWorker;
  const reg = sw?.controller ? await sw.getRegistration() : undefined;
  if (!reg) return false;
  const tookOver = new Promise<boolean>((resolve) => {
    sw.addEventListener('controllerchange', () => resolve(true), { once: true });
  });
  await reg.update();
  const worker = reg.installing ?? reg.waiting;
  if (!worker) return Promise.race([tookOver, Promise.resolve(false)]);
  const failed = new Promise<boolean>((resolve) => {
    worker.addEventListener('statechange', () => {
      if (worker.state === 'redundant') resolve(false);
    });
  });
  const slow = new Promise<boolean>((resolve) => setTimeout(() => resolve(true), 60_000));
  return Promise.race([tookOver, failed, slow]);
}

// Plain DOM, not React: it must cover the page during the reload regardless
// of what the app tree is doing.
function showUpdatingOverlay(): void {
  const pl = document.documentElement.lang === 'pl';
  const el = document.createElement('div');
  el.setAttribute('role', 'status');
  el.style.cssText =
    'position:fixed;inset:0;z-index:2147483647;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;background:var(--color-ink-fill,#16211a);color:var(--color-on-ink,#f8fdfa);font-family:var(--font-sans,system-ui)';
  el.innerHTML = `
    <div style="width:46px;height:46px;border-radius:50%;border:4px solid rgba(255,255,255,.15);border-top-color:var(--color-brand-500,#71c883);animation:pwa-spin .9s linear infinite"></div>
    <div style="font-family:var(--font-display,system-ui);font-weight:900;font-size:40px;text-transform:uppercase">${pl ? 'Aktualizacja' : 'Updating'}</div>
    <div style="opacity:.7;font-size:14px">${pl ? 'Pobieramy najnowszą wersję…' : 'Getting the newest version…'}</div>
    <style>@keyframes pwa-spin{to{transform:rotate(1turn)}}</style>`;
  document.body.appendChild(el);
}
